// Vitest Context Window Chunking Safeguard
import { describe, it, expect } from 'vitest';

describe('LegalContractSummarizer - Chunking Safeguard', () => {
  it('splits 134k token payload into chunks smaller than 8000 tokens', () => {
    const totalTokens = 134200;
    const chunkSize = 8000;
    const chunks = Math.ceil(totalTokens / chunkSize);
    expect(chunks).toBe(17);
    expect(chunkSize).toBeLessThan(131072);
  });
});
